from cloud.services.agent_runner.langfuse.graph_operations import (
    LangfuseGraphOperationObserver,
)


def _graph_operation_observer(
    observer: LangfuseRunObserver | None,
) -> LangfuseGraphOperationObserver | None:
    if observer is None or observer.handles is None:
        return None
    return LangfuseGraphOperationObserver(handles=observer.handles)
    run_ctx.graph_operation_observer = _graph_operation_observer(observer)
